<script setup lang="ts">import type {RankRow} from '../types/domain';defineProps<{rows:RankRow[];total:number}>();const ticks=(total:number)=>[...new Set([1,Math.max(1,Math.round(total/4)),Math.max(1,Math.round(total/2)),Math.round(total*3/4),total])];const scale=(v:number,total:number)=>170+(v-1)/Math.max(1,total-1)*535;</script><template><div class="rank-chart-scroll"><svg class="rank-chart" :viewBox="`0 0 760 ${85+rows.length*32}`" role="img" aria-label="权重情景名次的真实经验分位范围"><g v-for="i in ticks(total)" :key="i"><line :x1="scale(i,total)" :x2="scale(i,total)" y1="40" :y2="60+rows.length*32" stroke="currentColor" opacity=".12"/><text :x="scale(i,total)" y="28" text-anchor="middle" class="axis-text">第{{i}}名</text></g><g v-for="(r,i) in rows" :key="r.id"><text x="0" :y="65+i*32" class="rank-label">{{r.code}}　{{r.name}}</text><line :x1="scale(r.rank_low,total)" :x2="scale(r.rank_high,total)" :y1="60+i*32" :y2="60+i*32" stroke="var(--moss)" stroke-width="6" opacity=".55"/><circle :cx="scale(r.rank,total)" :cy="60+i*32" r="4" fill="var(--ink)"/><title>{{r.name}}；中心名次{{r.rank}}；经验分位{{r.rank_low}}–{{r.rank_high}}；实际最好/最差{{r.rank_min}}–{{r.rank_max}}</title></g></svg></div></template>